MonarchUsernameAvailabilityInput(
    {{label}},
    text: $address,
    prompt: {{placeholder}},
    helper: {{description}},
    prefix: {{prefix}},
    isRequired: {{required}}
) { address in
    MonarchUsernameAvailabilityResult(isValid: ![{{taken.0}}, {{taken.1}}, {{taken.2}}, {{taken.3}}].contains(address))
}
